from collections import OrderedDict
class TTLCache:
    def __init__(self, capacity):
        if capacity < 0: raise ValueError('capacity')
        self.capacity = capacity
        self.data = OrderedDict()
    def purge(self, now):
        for key in list(self.data):
            if self.data[key][1] <= now: del self.data[key]
    def put(self, key, value, ttl, now):
        self.purge(now)
        self.data.pop(key, None)
        if ttl <= 0 or self.capacity == 0: return
        self.data[key] = (value, now + ttl)
        while len(self.data) > self.capacity: self.data.popitem(last=False)
    def get(self, key, now, default=None):
        self.purge(now)
        if key not in self.data: return default
        self.data.move_to_end(key)
        return self.data[key][0]

