def subtract_ranges(bounds, blocked):
    lo, hi = bounds
    cursor = lo
    result = []
    for a,b in sorted(blocked):
        a,b = max(a,lo),min(b,hi)
        if a >= b: continue
        if a > cursor: result.append((cursor,a))
        cursor = max(cursor,b)
    if cursor < hi: result.append((cursor,hi))
    return result

def shortest_cost(n, edges, src, dst):
    d=[float('inf')]*n; d[src]=0
    for _ in range(n-1):
        changed=False
        for u,v,w in edges:
            if d[u]!=float('inf') and d[u]+w < d[v]: d[v]=d[u]+w; changed=True
        if not changed: break
    bad={v for u,v,w in edges if d[u]!=float('inf') and d[u]+w < d[v]}
    for _ in range(n):
        bad.update(v for u,v,w in edges if u in bad)
    if dst in bad: raise ValueError('unbounded')
    return None if d[dst]==float('inf') else d[dst]

