def parse_pairs(text):
    if text=='': return []
    out=[]; key=[]; value=[]; separated=False; escaped=False
    for ch in text+';':
        if escaped:
            if ch not in ';=\\': raise ValueError('escape')
            (value if separated else key).append(ch); escaped=False
        elif ch=='\\': escaped=True
        elif ch==';':
            if not separated or not key: raise ValueError('record')
            out.append((''.join(key),''.join(value))); key=[]; value=[]; separated=False
        elif ch=='=' and not separated: separated=True
        else: (value if separated else key).append(ch)
    if escaped or key or value or separated: raise ValueError('unfinished')
    return out

