import heapq
def assign_rooms(meetings):
    busy=[]; free=[]; count=0; result=[0]*len(meetings)
    for i,(start,end) in sorted(enumerate(meetings),key=lambda p:(p[1][0],p[1][1],p[0])):
        while busy and busy[0][0]<=start:
            _,room=heapq.heappop(busy); heapq.heappush(free,room)
        if free: room=heapq.heappop(free)
        else: room=count; count+=1
        result[i]=room; heapq.heappush(busy,(end,room))
    return result

import codecs
def decode_utf8(chunks):
    decoder=codecs.getincrementaldecoder('utf-8')('strict')
    parts=[decoder.decode(chunk,final=False) for chunk in chunks]
    parts.append(decoder.decode(b'',final=True))
    return ''.join(parts)

