def parse_netstrings(data):
    result=[]; pos=0
    while pos<len(data):
        colon=data.find(b':',pos)
        if colon<0: raise ValueError('header')
        header=data[pos:colon]
        if not header or any(c<48 or c>57 for c in header): raise ValueError('digits')
        if len(header)>1 and header[0]==48: raise ValueError('leading zero')
        n=int(header); start=colon+1; end=start+n
        if end>=len(data) or data[end]!=44: raise ValueError('length/comma')
        result.append(data[start:end]); pos=end+1
    return result

