def allocate_cents(total, weights):
    if not weights:
        if total: raise ValueError('empty')
        return []
    denominator=sum(weights)
    if denominator==0: raise ValueError('zero')
    result=[total*w//denominator for w in weights]
    order=sorted(range(len(weights)),key=lambda i:(-(total*weights[i]%denominator),i))
    for i in order[:total-sum(result)]: result[i]+=1
    return result

def apply_edits(text, edits):
    for start,end,_ in edits:
        if not 0<=start<=end<=len(text): raise ValueError('range')
    ordered=sorted(enumerate(edits),key=lambda x:(x[1][0],x[1][1],x[0]))
    cursor=0; parts=[]
    for _,(start,end,replacement) in ordered:
        if start<cursor: raise ValueError('overlap')
        parts.extend((text[cursor:start],replacement)); cursor=end
    parts.append(text[cursor:])
    return ''.join(parts)

