from collections import deque,Counter
def window_counts(events,width):
    if width<=0: raise ValueError('width')
    queue=deque(); counts=Counter(); result=[]
    for t,k in events:
        while queue and queue[0][0]<=t-width:
            _,old=queue.popleft(); counts[old]-=1
            if not counts[old]: del counts[old]
        queue.append((t,k)); counts[k]+=1; result.append(counts[k])
    return result

import re
def evaluate(expression):
    tokens=re.findall(r'[0-9]+|[+*()-]|[^ \t\n]',expression); pos=0
    def factor():
        nonlocal pos
        if pos>=len(tokens): raise ValueError('operand')
        t=tokens[pos]; pos+=1
        if t in ('+','-'):
            v=factor(); return v if t=='+' else -v
        if t=='(':
            v=expr()
            if pos>=len(tokens) or tokens[pos]!=')': raise ValueError('parenthesis')
            pos+=1; return v
        if re.fullmatch('[0-9]+',t): return int(t)
        raise ValueError('token')
    def term():
        nonlocal pos
        v=factor()
        while pos<len(tokens) and tokens[pos]=='*': pos+=1; v*=factor()
        return v
    def expr():
        nonlocal pos
        v=term()
        while pos<len(tokens) and tokens[pos] in ('+','-'):
            op=tokens[pos]; pos+=1; w=term(); v=v+w if op=='+' else v-w
        return v
    result=expr()
    if pos!=len(tokens): raise ValueError('leftovers')
    return result

def resolve_aliases(mapping):
    resolved={}
    for key in mapping:
        path=[]; seen=set(); current=key
        while current in mapping and current not in resolved:
            if current in seen: raise ValueError('cycle')
            seen.add(current); path.append(current); current=mapping[current]
        terminal=resolved.get(current,current)
        for item in path: resolved[item]=terminal
    return resolved

